public abstract class BaseExercise : Form { protected FlowLayoutPanel Panel; protected BaseExercise(string title) { Text=title;Width=900;Height=650;StartPosition=FormStartPosition.CenterScreen;Panel=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,AutoScroll=true,Padding=new Padding(18),WrapContents=false};Controls.Add(Panel); } protected TextBox Field(string label) {var row=new FlowLayoutPanel{Width=800,Height=38};row.Controls.Add(new Label{Text=label,Width=140,TextAlign=ContentAlignment.MiddleLeft});var t=new TextBox{Width=420};row.Controls.Add(t);Panel.Controls.Add(row);return t;} protected Button Action(string title,Action handler){var b=new Button{Text=title,Width=190,Height=36};b.Click+=(s,e)=>{try{handler();}catch(Exception ex){MessageBox.Show(ex.Message);}};Panel.Controls.Add(b);return b;} protected void Warn(string message)=>MessageBox.Show(message,"Thông báo");protected bool Confirm()=>MessageBox.Show("Bạn có chắc chắn?","Xác nhận",MessageBoxButtons.YesNo)==DialogResult.Yes; }

public class Exercise1:BaseExercise {public Exercise1():base("DANH SÁCH SINH VIÊN"){var name=Field("Họ và tên");var id=Field("Mã sinh viên");var gender=new ComboBox{Width=220,DropDownStyle=ComboBoxStyle.DropDownList};gender.Items.AddRange(new object[]{"Nam","Nữ"});gender.SelectedIndex=0;Panel.Controls.Add(gender);var languages=Field("Ngoại ngữ (cách nhau ,)");var ethnic=new ComboBox{Width=200,DropDownStyle=ComboBoxStyle.DropDownList};ethnic.Items.AddRange(new object[]{"Kinh","Hoa","Khmer","H'Mông","Khác"});ethnic.SelectedIndex=0;Panel.Controls.Add(ethnic);var list=new ListView{Width=800,Height=230,View=View.Details,FullRowSelect=true,GridLines=true};foreach(string s in new[]{"Họ tên","Mã sinh viên","Giới tính","Ngoại ngữ","Dân tộc"})list.Columns.Add(s,145);Panel.Controls.Add(list);Action("Thêm",()=>{if(name.Text.Trim()==""||id.Text.Trim()=="")throw new Exception("Nhập họ tên và mã SV");if(list.Items.Cast<ListViewItem>().Any(x=>x.SubItems[1].Text==id.Text.Trim()))throw new Exception("Trùng mã sinh viên");list.Items.Add(new ListViewItem(new[]{name.Text.Trim(),id.Text.Trim(),gender.Text,languages.Text,ethnic.Text}));});Action("Sửa",()=>{if(list.SelectedItems.Count==0)throw new Exception("Chọn sinh viên");var x=list.SelectedItems[0];x.SubItems[0].Text=name.Text;x.SubItems[2].Text=gender.Text;x.SubItems[3].Text=languages.Text;x.SubItems[4].Text=ethnic.Text;});Action("Xóa",Delete);void Delete(){if(list.SelectedItems.Count==0)throw new Exception("Chọn sinh viên");if(Confirm())foreach(var x in list.SelectedItems.Cast<ListViewItem>().ToArray())list.Items.Remove(x);}var menu=new ContextMenuStrip();menu.Items.Add("Xóa",null,(s,e)=>Delete());list.ContextMenuStrip=menu;list.SelectedIndexChanged+=(s,e)=>{if(list.SelectedItems.Count==0)return;var x=list.SelectedItems[0];name.Text=x.Text;id.Text=x.SubItems[1].Text;gender.Text=x.SubItems[2].Text;languages.Text=x.SubItems[3].Text;ethnic.Text=x.SubItems[4].Text;};FormClosing+=(s,e)=>{if(!Confirm())e.Cancel=true;};}}
public class Exercise2:BaseExercise {public Exercise2():base("QUẢN LÝ THÔNG TIN TÀI KHOẢN"){var number=Field("Số tài khoản");var name=Field("Tên khách hàng");var address=Field("Địa chỉ");var money=Field("Số tiền");var list=new ListView{Width=800,Height=240,View=View.Details,FullRowSelect=true,GridLines=true};foreach(string s in new[]{"STT","Số tài khoản","Tên khách hàng","Địa chỉ","Số tiền"})list.Columns.Add(s,150);Panel.Controls.Add(list);var total=new Label{Width=650,Height=30};Panel.Controls.Add(total);bool adding=false;Button? save=null,delete=null;Button add=null!;add=Action("Thêm",()=>{adding=!adding;number.Clear();name.Clear();address.Clear();money.Clear();number.Focus();save!.Enabled=adding;add.Text=adding?"Hủy":"Thêm";});save=Action("Lưu",()=>{if(!adding)return;if(new[]{number.Text,name.Text,address.Text,money.Text}.Any(string.IsNullOrWhiteSpace)||!decimal.TryParse(money.Text,out decimal m)||m<0)throw new Exception("Dữ liệu không hợp lệ");if(list.Items.Cast<ListViewItem>().Any(x=>x.SubItems[1].Text==number.Text))throw new Exception("Trùng tài khoản");list.Items.Add(new ListViewItem(new[]{"",number.Text,name.Text,address.Text,m.ToString("N0")}));adding=false;add.Text="Thêm";save.Enabled=false;Refresh();});save.Enabled=false;delete=Action("Xóa",()=>{if(list.SelectedItems.Count==0)return;if(Confirm()){list.SelectedItems[0].Remove();Refresh();}});delete.Enabled=false;list.SelectedIndexChanged+=(s,e)=>{delete.Enabled=list.SelectedItems.Count>0;if(list.SelectedItems.Count==0)return;var x=list.SelectedItems[0];number.Text=x.SubItems[1].Text;name.Text=x.SubItems[2].Text;address.Text=x.SubItems[3].Text;money.Text=x.SubItems[4].Text;};Action("Thoát",()=>{if(Confirm())Close();});void Refresh(){decimal sum=0;for(int i=0;i<list.Items.Count;i++){var x=list.Items[i];x.Text=(i+1).ToString();sum+=decimal.Parse(x.SubItems[4].Text,System.Globalization.NumberStyles.Number);}total.Text="Tổng tiền: "+sum.ToString("N0");}}}
public class Exercise3:BaseExercise {public Exercise3():base("QUẢN LÝ HỌC VIÊN"){var a=new ListBox{Width=330,Height=230,SelectionMode=SelectionMode.MultiExtended};var b=new ListBox{Width=330,Height=230,SelectionMode=SelectionMode.MultiExtended};Panel.Controls.Add(new Label{Text="Lớp A",Width=300});Panel.Controls.Add(a);Panel.Controls.Add(new Label{Text="Lớp B",Width=300});Panel.Controls.Add(b);foreach(string s in new[]{"Trần Hùng","Nguyễn Hương","Lâm Tư"})a.Items.Add(s);foreach(string s in new[]{"Trần Hưng","Hoàng Ngọc","Anh Minh","Bảo Lâm"})b.Items.Add(s);void Move(ListBox from,ListBox to){var selected=from.SelectedItems.Cast<object>().ToArray();if(selected.Length==0){Warn("Hãy chọn học viên");return;}foreach(var x in selected){to.Items.Add(x);from.Items.Remove(x);}}Action("Chuyển sang lớp A",()=>Move(b,a));Action("Chuyển sang lớp B",()=>Move(a,b));Action("Xóa học viên",()=>{foreach(var l in new[]{a,b})foreach(var x in l.SelectedItems.Cast<object>().ToArray())l.Items.Remove(x);});Action("Nhập học viên mới",()=>{var form=new Form{Text="Nhập học viên",Width=430,Height=220};var t=new TextBox{Left=100,Top=25,Width=270};var c=new ComboBox{Left=100,Top=65,Width=270,DropDownStyle=ComboBoxStyle.DropDownList};c.Items.AddRange(new object[]{"Lớp A","Lớp B"});c.SelectedIndex=0;var ok=new Button{Text="Cập nhật",Left=100,Top=105};var back=new Button{Text="Trở về",Left=230,Top=105};form.Controls.AddRange(new Control[]{new Label{Text="Họ và tên",Left=10,Top=28},new Label{Text="Lớp",Left=10,Top=68},t,c,ok,back});ok.Click+=(s,e)=>{if(string.IsNullOrWhiteSpace(t.Text)){Warn("Nhập họ tên");t.Focus();return;}(c.SelectedIndex==0?a:b).Items.Add(t.Text.Trim());form.Close();};back.Click+=(s,e)=>form.Close();form.ShowDialog(this);});Action("Kết thúc",()=>{if(Confirm())Close();});}}
public class Exercise4:BaseExercise {public Exercise4():base("ĐỒNG HỒ ĐẾM NGƯỢC"){int remaining=30;var label=new Label{Text="00:30",Font=new Font("Arial",30,FontStyle.Bold),Width=300,Height=75};Panel.Controls.Add(label);var timer=new System.Windows.Forms.Timer{Interval=1000};var start=Action("Bắt đầu",()=>{remaining=30;label.Text="00:30";timer.Start();});timer.Tick+=(s,e)=>{remaining--;label.Text=$"00:{remaining:00}";if(remaining<=0){timer.Stop();Warn("Hết giờ!");}};}}
public class Exercise5:BaseExercise {public Exercise5():base("MENU TỔNG HỢP"){var menu=new MenuStrip();Controls.Add(menu);MainMenuStrip=menu;for(int i=1;i<=4;i++){int n=i;menu.Items.Add("Bài "+i,null,(s,e)=>{switch(n){case 1:new Exercise1().Show();break;case 2:new Exercise2().Show();break;case 3:new Exercise3().Show();break;case 4:new Exercise4().Show();break;}});}Panel.Controls.Add(new Label{Text="Chọn bài tập từ MenuStrip phía trên.",Width=600});}}

public class SqlCrudForm:BaseExercise {readonly string table;readonly string[] columns;readonly TextBox[] fields;readonly string[] keys;readonly bool partial;public SqlCrudForm(string title,string table,string[] cols,string[] keys,bool partial=false):base(title){this.table=table;columns=cols;this.keys=keys;this.partial=partial;fields=cols.Select(Field).ToArray();Panel.Controls.Add(new Label{Text="Cấu hình chuỗi kết nối trong appsettings.txt; SQL Server phải có CSDL QLSinhVien.",Width=800,Height=35});Action("Thêm",()=>Run("insert"));Action("Xóa",()=>Run("delete"));Action("Sửa",()=>Run("update"));}void Run(string mode){var values=columns.Zip(fields,(c,t)=>(c,value:t.Text.Trim())).ToDictionary(x=>x.c,x=>x.value);var required=mode=="delete"?keys:mode=="insert"?columns:keys;if(required.Any(k=>string.IsNullOrWhiteSpace(values[k])))throw new Exception("Thiếu trường bắt buộc");if(mode=="update"&&!columns.Except(keys).Any(k=>!string.IsNullOrWhiteSpace(values[k])))throw new Exception("Cần nhập trường muốn sửa");if(table=="Diem"&&mode!="delete"&&(!decimal.TryParse(values["Diem"],out var point)||point<0||point>10))throw new Exception("Điểm phải từ 0 đến 10");if(table=="SinhVien"&&mode=="insert"&&!DateTime.TryParse(values["NgaySinh"],out _))throw new Exception("Ngày sinh không hợp lệ");string[] updates=columns.Except(keys).Where(k=>!partial||!string.IsNullOrWhiteSpace(values[k])).ToArray();string where=string.Join(" AND ",keys.Select(k=>$"[{k}]=@{k}"));string sql=mode switch{"insert"=>$"INSERT INTO [{table}] ({string.Join(",",columns.Select(c=>$"[{c}]"))}) VALUES ({string.Join(",",columns.Select(c=>"@"+c))})","delete"=>$"DELETE FROM [{table}] WHERE {where}",_=>$"UPDATE [{table}] SET {string.Join(",",updates.Select(c=>$"[{c}]=@{c}"))} WHERE {where}"};string config=Path.Combine(AppContext.BaseDirectory,"appsettings.txt");if(!File.Exists(config))throw new Exception("Thiếu appsettings.txt. Hãy tạo chuỗi kết nối SQL Server.");using var conn=new Microsoft.Data.SqlClient.SqlConnection(File.ReadAllText(config).Trim());using var cmd=new Microsoft.Data.SqlClient.SqlCommand(sql,conn);foreach(var k in columns){object value=values[k];if(k=="NgaySinh"&&DateTime.TryParse(values[k],out var date))value=date;if(k=="Diem"&&decimal.TryParse(values[k],out var d))value=d;cmd.Parameters.AddWithValue("@"+k,value);}conn.Open();int count=cmd.ExecuteNonQuery();Warn(count>0?"Thao tác thành công":"Không tìm thấy dữ liệu phù hợp");}}
